                let seq0: Seq<char> = s.as_seq();
                if count_SF(seq0) > count_FS(seq0) {
                    // if more S→F than F→S, return ['Y','E','S']
                    result == vec!['Y','E','S']
                } else {
                    // otherwise return ['N','O']
                    result == vec!['N','O']
                }
